    const COL_TYPE_BOOL: i32 = 3;
    const MAX_COLS: i32 = 16;
    const MAX_ROWS: i32 = 1024;
    const SCHEMA_OK: i32 = 0;
    const SCHEMA_ERR_FULL: i32 = 1;
    const SCHEMA_ERR_NOT_FOUND: i32 = 2;

    struct ColumnDef {
        name:       string;
        col_type:   i32;
        nullable:   bool;
    }

    struct TableSchema {
        name:        string;
        col_defs:    [ColumnDef];
        col_count:   i32;
        primary_key: i32;   // 컬럼 인덱스 (기본 0)
    }

    struct RecordRow {
        row_id:     i64;
        int_vals:   [i64];   // COL_TYPE_INT 컬럼 값
        str_vals:   [string]; // COL_TYPE_STR 컬럼 값
        bool_vals:  [bool];  // COL_TYPE_BOOL 컬럼 값
        is_deleted: bool;
    }

    struct Table {
        schema:         TableSchema;
        // SoA 플래튼 배열: int_cols[col_idx * MAX_ROWS + row_idx]
        int_cols:       [i64];
        str_cols:       [string];
        bool_cols:      [bool];
        deleted_flags:  [bool];   // 소프트 삭제
        row_ids:        [i64];    // 각 행의 ID
        row_count:      i32;
        next_id:        i64;
    }
}
```

