        col_count:   i32;
        primary_key: i32;    // 기본키 컬럼 인덱스 (0 = 첫 번째)
    }

    // 행 레코드 (SELECT 결과)
    struct RecordRow {
        row_id:     i64;
        int_vals:   [i64];
        str_vals:   [string];
        bool_vals:  [bool];
        is_deleted: bool;
    }

    // 테이블 (SoA 레이아웃)
    struct Table {
        schema:        TableSchema;
        // 플래튼 SoA 배열: [col_idx * MAX_ROWS + row_idx]
        int_cols:      [i64];
        str_cols:      [string];
        bool_cols:     [bool];
        // 메타데이터
        deleted_flags: [bool];
        row_ids:       [i64];
        row_count:     i32;
        next_id:       i64;
    }

    // === 스키마 함수 ===

    // 스키마 생성
    func schema_new(name: string) -> TableSchema {
        return TableSchema{
            name:        name,
            col_defs:    make([ColumnDef], MAX_COLS),
            col_count:   0,
            primary_key: 0,
        };
    }

    // 컬럼 추가
    func (s: *TableSchema) schema_add_col(name: string, col_type: i32, nullable: bool) -> bool {
        if s.col_count >= MAX_COLS {
            return false;
        }
        s.col_defs[s.col_count] = ColumnDef{
            name:     name,
            col_type: col_type,
            nullable: nullable,
        };
        s.col_count = s.col_count + 1;
        return true;
    }

    // 컬럼 이름으로 인덱스 찾기
    func (s: *TableSchema) schema_find_col(name: string) -> (i32, bool) {
        let i = 0;
        for i = 0; i < s.col_count; i = i + 1 {
            if s.col_defs[i].name == name {
                return (i, true);
            }
        }
        return (-1, false);
    }

    // 특정 타입 컬럼의 타입 내부 인덱스 계산
    // (int_cols 배열 내에서 col_idx번째 INT 컬럼의 순서)
    @inline
    func (s: *TableSchema) col_type_idx(col_idx: i32) -> i32 {
        let count = 0;
        let target_type = s.col_defs[col_idx].col_type;
        let i = 0;
        for i = 0; i < col_idx; i = i + 1 {
            if s.col_defs[i].col_type == target_type {
                count = count + 1;
            }
        }
        return count;
    }

    // 타입별 컬럼 수 계산
    @inline
    func (s: *TableSchema) count_cols_of_type(col_type: i32) -> i32 {
        let count = 0;
        let i = 0;
        for i = 0; i < s.col_count; i = i + 1 {
            if s.col_defs[i].col_type == col_type {
                count = count + 1;
            }
        }
        return count;
    }

    // === 테이블 함수 ===

    // 테이블 생성 (SoA 배열 초기화)
    func table_new(s: TableSchema) -> Table {
        return Table{
            schema:        s,
            int_cols:      make([i64],    MAX_COLS * MAX_ROWS),
            str_cols:      make([string], MAX_COLS * MAX_ROWS),
            bool_cols:     make([bool],   MAX_COLS * MAX_ROWS),
            deleted_flags: make([bool],   MAX_ROWS),
            row_ids:       make([i64],    MAX_ROWS),
            row_count:     0,
            next_id:       1,
        };
    }

    // 행 삽입 (row_id 반환)
    func (t: *Table) table_insert(row: RecordRow) -> (i64, bool) {
        if t.row_count >= MAX_ROWS {
            return (0, false);
        }

        let row_idx = t.row_count;
        let row_id = t.next_id;

        // row_id 및 삭제 플래그 기록
        t.row_ids[row_idx] = row_id;
        t.deleted_flags[row_idx] = false;

        // INT 컬럼 저장
        let int_type_idx = 0;
        let i = 0;
        for i = 0; i < t.schema.col_count; i = i + 1 {
            if t.schema.col_defs[i].col_type == COL_TYPE_INT {
                let flat_idx = i * MAX_ROWS + row_idx;
                if int_type_idx < MAX_COLS {
                    t.int_cols[flat_idx] = row.int_vals[int_type_idx];
                }
                int_type_idx = int_type_idx + 1;
            }
        }

        // STR 컬럼 저장
        let str_type_idx = 0;
        for i = 0; i < t.schema.col_count; i = i + 1 {
            if t.schema.col_defs[i].col_type == COL_TYPE_STR {
                let flat_idx = i * MAX_ROWS + row_idx;
                if str_type_idx < MAX_COLS {
                    t.str_cols[flat_idx] = row.str_vals[str_type_idx];
                }
                str_type_idx = str_type_idx + 1;
            }
        }

        // BOOL 컬럼 저장
        let bool_type_idx = 0;
        for i = 0; i < t.schema.col_count; i = i + 1 {
            if t.schema.col_defs[i].col_type == COL_TYPE_BOOL {
                let flat_idx = i * MAX_ROWS + row_idx;
                if bool_type_idx < MAX_COLS {
                    t.bool_cols[flat_idx] = row.bool_vals[bool_type_idx];
                }
                bool_type_idx = bool_type_idx + 1;
            }
        }

        t.row_count = t.row_count + 1;
        t.next_id = t.next_id + 1;
        return (row_id, true);
    }

    // row_id → row_idx 변환 (선형 탐색)
    @inline
    func (t: *Table) find_row_idx(row_id: i64) -> (i32, bool) {
        let i = 0;
        for i = 0; i < t.row_count; i = i + 1 {
            if t.row_ids[i] == row_id && !t.deleted_flags[i] {
                return (i, true);
            }
        }
        return (-1, false);
    }

    // row_idx → RecordRow 변환
    func (t: *Table) row_to_record(row_idx: i32) -> RecordRow {
        let row = RecordRow{
            row_id:     t.row_ids[row_idx],
            int_vals:   make([i64],    MAX_COLS),
            str_vals:   make([string], MAX_COLS),
            bool_vals:  make([bool],   MAX_COLS),
            is_deleted: t.deleted_flags[row_idx],
        };

        // INT 컬럼 추출
        let int_type_idx = 0;
        let i = 0;
        for i = 0; i < t.schema.col_count; i = i + 1 {
            if t.schema.col_defs[i].col_type == COL_TYPE_INT {
                row.int_vals[int_type_idx] = t.int_cols[i * MAX_ROWS + row_idx];
                int_type_idx = int_type_idx + 1;
            }
        }

        // STR 컬럼 추출
        let str_type_idx = 0;
        for i = 0; i < t.schema.col_count; i = i + 1 {
            if t.schema.col_defs[i].col_type == COL_TYPE_STR {
                row.str_vals[str_type_idx] = t.str_cols[i * MAX_ROWS + row_idx];
                str_type_idx = str_type_idx + 1;
            }
        }

        // BOOL 컬럼 추출
        let bool_type_idx = 0;
        for i = 0; i < t.schema.col_count; i = i + 1 {
            if t.schema.col_defs[i].col_type == COL_TYPE_BOOL {
                row.bool_vals[bool_type_idx] = t.bool_cols[i * MAX_ROWS + row_idx];
                bool_type_idx = bool_type_idx + 1;
            }
        }

        return row;
    }

    // ID로 행 조회
    func (t: *Table) table_get(row_id: i64) -> (RecordRow, bool) {
        let row_idx, found = t.find_row_idx(row_id);
        if !found {
            return (RecordRow{
                row_id:     0,
                int_vals:   make([i64], MAX_COLS),
                str_vals:   make([string], MAX_COLS),
                bool_vals:  make([bool], MAX_COLS),
                is_deleted: true,
            }, false);
        }
        return (t.row_to_record(row_idx), true);
    }

    // INT 컬럼 업데이트
    func (t: *Table) table_update_int(row_id: i64, col_idx: i32, val: i64) -> bool {
        if col_idx < 0 || col_idx >= t.schema.col_count {
            return false;
        }
        if t.schema.col_defs[col_idx].col_type != COL_TYPE_INT {
            return false;
        }
        let row_idx, found = t.find_row_idx(row_id);
        if !found {
            return false;
        }
        t.int_cols[col_idx * MAX_ROWS + row_idx] = val;
        return true;
    }

    // STR 컬럼 업데이트
    func (t: *Table) table_update_str(row_id: i64, col_idx: i32, val: string) -> bool {
        if col_idx < 0 || col_idx >= t.schema.col_count {
            return false;
        }
        if t.schema.col_defs[col_idx].col_type != COL_TYPE_STR {
            return false;
        }
        let row_idx, found = t.find_row_idx(row_id);
        if !found {
            return false;
        }
        t.str_cols[col_idx * MAX_ROWS + row_idx] = val;
        return true;
    }

    // BOOL 컬럼 업데이트
    func (t: *Table) table_update_bool(row_id: i64, col_idx: i32, val: bool) -> bool {
        if col_idx < 0 || col_idx >= t.schema.col_count {
            return false;
        }
        if t.schema.col_defs[col_idx].col_type != COL_TYPE_BOOL {
            return false;
        }
        let row_idx, found = t.find_row_idx(row_id);
        if !found {
            return false;
        }
        t.bool_cols[col_idx * MAX_ROWS + row_idx] = val;
        return true;
    }

    // 소프트 삭제
    func (t: *Table) table_delete(row_id: i64) -> bool {
        let row_idx, found = t.find_row_idx(row_id);
        if !found {
            return false;
        }
        t.deleted_flags[row_idx] = true;
        return true;
    }

    // 살아있는 행 수
    func (t: *Table) table_count() -> i32 {
        let count = 0;
        let i = 0;
        for i = 0; i < t.row_count; i = i + 1 {
            if !t.deleted_flags[i] {
                count = count + 1;
            }
        }
        return count;
    }

    // 인덱스로 행 조회 (query.fl 내부 사용)
    func (t: *Table) table_get_row(row_idx: i32) -> RecordRow {
        return t.row_to_record(row_idx);
    }

    // 행이 살아있는지 확인
    @inline
    func (t: *Table) is_alive(row_idx: i32) -> bool {
        return row_idx >= 0 && row_idx < t.row_count && !t.deleted_flags[row_idx];
    }

    // INT 컬럼 값 직접 접근 (query.fl 최적화용)
    @inline
    func (t: *Table) get_int_val(row_idx: i32, col_idx: i32) -> i64 {
        return t.int_cols[col_idx * MAX_ROWS + row_idx];
    }

    // STR 컬럼 값 직접 접근
    @inline
    func (t: *Table) get_str_val(row_idx: i32, col_idx: i32) -> string {
        return t.str_cols[col_idx * MAX_ROWS + row_idx];
    }

    // BOOL 컬럼 값 직접 접근
    @inline
    func (t: *Table) get_bool_val(row_idx: i32, col_idx: i32) -> bool {
        return t.bool_cols[col_idx * MAX_ROWS + row_idx];
    }

    // RecordRow 생성 헬퍼
    func record_new() -> RecordRow {
        return RecordRow{
            row_id:     0,
            int_vals:   make([i64],    MAX_COLS),
            str_vals:   make([string], MAX_COLS),
            bool_vals:  make([bool],   MAX_COLS),
            is_deleted: false,
        };
    }

    // === 통계 함수 ===

    func (t: *Table) table_stats() -> string {
        let alive = t.table_count();
        let msg = "[Table " + t.schema.name + "] rows=" + i32_to_str(t.row_count) +
                  " alive=" + i32_to_str(alive) +
                  " deleted=" + i32_to_str(t.row_count - alive) +
                  " cols=" + i32_to_str(t.schema.col_count) +
                  " next_id=" + i64_to_str(t.next_id);
        return msg;
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_str(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n == 6 { return "6"; }
        if n == 7 { return "7"; }
        if n == 8 { return "8"; }
        if n == 9 { return "9"; }
        if n < 0 { return "-" + i32_to_str(-n); }
        let d = n / 10;
        let r = n % 10;
        return i32_to_str(d) + i32_to_str(r);
    }

    @inline
    func i64_to_str(n: i64) -> string {
        if n == 0 { return "0"; }
        if n < 0 { return "-" + i64_to_str(-n); }
        return i32_to_str(i32(n));
    }
}

