            }
        }

        t.row_count = t.row_count + 1;
        t.next_id = t.next_id + 1;
        return (row_id, true);
    }

    // row_id → row_idx 변환 (선형 탐색)
    @inline
    func (t: *Table) find_row_idx(row_id: i64) -> (i32, bool) {
        let i = 0;
        for i = 0; i < t.row_count; i = i + 1 {
            if t.row_ids[i] == row_id && !t.deleted_flags[i] {
                return (i, true);
            }
        }
        return (-1, false);
    }

    // row_idx → RecordRow 변환
    func (t: *Table) row_to_record(row_idx: i32) -> RecordRow {
        let row = RecordRow{
            row_id:     t.row_ids[row_idx],
            int_vals:   make([i64],    MAX_COLS),
            str_vals:   make([string], MAX_COLS),
            bool_vals:  make([bool],   MAX_COLS),
            is_deleted: t.deleted_flags[row_idx],
        };

        // INT 컬럼 추출
        let int_type_idx = 0;
        let i = 0;
        for i = 0; i < t.schema.col_count; i = i + 1 {
            if t.schema.col_defs[i].col_type == COL_TYPE_INT {
                row.int_vals[int_type_idx] = t.int_cols[i * MAX_ROWS + row_idx];
                int_type_idx = int_type_idx + 1;
            }
        }

        // STR 컬럼 추출
        let str_type_idx = 0;
        for i = 0; i < t.schema.col_count; i = i + 1 {
            if t.schema.col_defs[i].col_type == COL_TYPE_STR {
                row.str_vals[str_type_idx] = t.str_cols[i * MAX_ROWS + row_idx];
                str_type_idx = str_type_idx + 1;
            }
        }

        // BOOL 컬럼 추출
        let bool_type_idx = 0;
        for i = 0; i < t.schema.col_count; i = i + 1 {
            if t.schema.col_defs[i].col_type == COL_TYPE_BOOL {
                row.bool_vals[bool_type_idx] = t.bool_cols[i * MAX_ROWS + row_idx];
                bool_type_idx = bool_type_idx + 1;
            }
        }

        return row;
    }

    // ID로 행 조회
    func (t: *Table) table_get(row_id: i64) -> (RecordRow, bool) {
        let row_idx, found = t.find_row_idx(row_id);
        if !found {
            return (RecordRow{
                row_id:     0,
                int_vals:   make([i64], MAX_COLS),
                str_vals:   make([string], MAX_COLS),
                bool_vals:  make([bool], MAX_COLS),
                is_deleted: true,
            }, false);
        }
        return (t.row_to_record(row_idx), true);
    }

    // INT 컬럼 업데이트
    func (t: *Table) table_update_int(row_id: i64, col_idx: i32, val: i64) -> bool {
        if col_idx < 0 || col_idx >= t.schema.col_count {
            return false;
        }
        if t.schema.col_defs[col_idx].col_type != COL_TYPE_INT {
            return false;
        }
        let row_idx, found = t.find_row_idx(row_id);
        if !found {
            return false;
        }
        t.int_cols[col_idx * MAX_ROWS + row_idx] = val;
        return true;
    }

    // STR 컬럼 업데이트
    func (t: *Table) table_update_str(row_id: i64, col_idx: i32, val: string) -> bool {
        if col_idx < 0 || col_idx >= t.schema.col_count {
            return false;
        }
        if t.schema.col_defs[col_idx].col_type != COL_TYPE_STR {
            return false;
        }
        let row_idx, found = t.find_row_idx(row_id);
        if !found {
            return false;
        }
        t.str_cols[col_idx * MAX_ROWS + row_idx] = val;
        return true;
    }

    // BOOL 컬럼 업데이트
    func (t: *Table) table_update_bool(row_id: i64, col_idx: i32, val: bool) -> bool {
        if col_idx < 0 || col_idx >= t.schema.col_count {
            return false;
        }
        if t.schema.col_defs[col_idx].col_type != COL_TYPE_BOOL {
            return false;
        }
        let row_idx, found = t.find_row_idx(row_id);
        if !found {
            return false;
        }
        t.bool_cols[col_idx * MAX_ROWS + row_idx] = val;
        return true;
    }

    // 소프트 삭제
    func (t: *Table) table_delete(row_id: i64) -> bool {
        let row_idx, found = t.find_row_idx(row_id);
        if !found {
            return false;
        }
        t.deleted_flags[row_idx] = true;
        return true;
    }

    // 살아있는 행 수
    func (t: *Table) table_count() -> i32 {
        let count = 0;
        let i = 0;
        for i = 0; i < t.row_count; i = i + 1 {
            if !t.deleted_flags[i] {
                count = count + 1;
            }
        }
        return count;
    }

    // 인덱스로 행 조회 (query.fl 내부 사용)
    func (t: *Table) table_get_row(row_idx: i32) -> RecordRow {
        return t.row_to_record(row_idx);
    }

    // 행이 살아있는지 확인
    @inline
    func (t: *Table) is_alive(row_idx: i32) -> bool {
        return row_idx >= 0 && row_idx < t.row_count && !t.deleted_flags[row_idx];
    }

    // INT 컬럼 값 직접 접근 (query.fl 최적화용)
    @inline
    func (t: *Table) get_int_val(row_idx: i32, col_idx: i32) -> i64 {
        return t.int_cols[col_idx * MAX_ROWS + row_idx];
    }

    // STR 컬럼 값 직접 접근
    @inline
    func (t: *Table) get_str_val(row_idx: i32, col_idx: i32) -> string {
        return t.str_cols[col_idx * MAX_ROWS + row_idx];
    }

    // BOOL 컬럼 값 직접 접근
    @inline
    func (t: *Table) get_bool_val(row_idx: i32, col_idx: i32) -> bool {
        return t.bool_cols[col_idx * MAX_ROWS + row_idx];
    }

    // RecordRow 생성 헬퍼
    func record_new() -> RecordRow {
        return RecordRow{
            row_id:     0,
            int_vals:   make([i64],    MAX_COLS),
            str_vals:   make([string], MAX_COLS),
            bool_vals:  make([bool],   MAX_COLS),
            is_deleted: false,
        };
    }

    // === 통계 함수 ===

    func (t: *Table) table_stats() -> string {
        let alive = t.table_count();
        let msg = "[Table " + t.schema.name + "] rows=" + i32_to_str(t.row_count) +
                  " alive=" + i32_to_str(alive) +
                  " deleted=" + i32_to_str(t.row_count - alive) +
                  " cols=" + i32_to_str(t.schema.col_count) +
                  " next_id=" + i64_to_str(t.next_id);
        return msg;
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_str(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n == 6 { return "6"; }
        if n == 7 { return "7"; }
        if n == 8 { return "8"; }
        if n == 9 { return "9"; }
        if n < 0 { return "-" + i32_to_str(-n); }
        let d = n / 10;
        let r = n % 10;
        return i32_to_str(d) + i32_to_str(r);
    }

    @inline
    func i64_to_str(n: i64) -> string {
        if n == 0 { return "0"; }
        if n < 0 { return "-" + i64_to_str(-n); }
        return i32_to_str(i32(n));
    }
}

