        let q = query.query_table(r.table);
        q.set_offset(page * page_size);
        q.set_limit(page_size);
        return query.execute(r.table, q);
    }

    // === 결과 유틸리티 ===

    // QueryResult에서 특정 행의 RecordRow 가져오기
    func (r: *Repository) result_get_row(result: query.QueryResult, result_idx: i32) -> (schema.RecordRow, bool) {
        if result_idx < 0 || result_idx >= result.row_count {
            return (schema.record_new(), false);
        }
        let row_idx = result.row_indices[result_idx];
