// ============================================================================
// FreeLang 쿼리 엔진 통합 테스트 - Phase 6
// ============================================================================
// 범위: schema, query, orm, transaction 4개 모듈 통합 검증
// 시나리오:
//   1. 스키마 생성 + 테이블 CRUD
//   2. WHERE/ORDER BY/LIMIT/OFFSET 복합 쿼리
//   3. 집계 함수 (COUNT/SUM/MAX/MIN)
//   4. ORM Repository CRUD 전체 플로우
//   5. 트랜잭션 BEGIN/COMMIT/ROLLBACK
// ============================================================================

module query_test {
    // === 테스트 유틸리티 ===

    struct TestResult {
        name:    string;
        passed:  bool;
        message: string;
    }

    func assert_true(condition: bool, name: string) -> TestResult {
        return TestResult{
            name:    name,
            passed:  condition,
            message: if condition { "PASS" } else { "FAIL" },
        };
    }

    func assert_eq_i32(actual: i32, expected: i32, name: string) -> TestResult {
        let passed = actual == expected;
        return TestResult{
            name:    name,
            passed:  passed,
            message: if passed { "PASS" } else { "FAIL: expected " + i32_to_str(expected) + " got " + i32_to_str(actual) },
        };
    }

    func assert_eq_i64(actual: i64, expected: i64, name: string) -> TestResult {
        let passed = actual == expected;
        return TestResult{
            name:    name,
            passed:  passed,
            message: if passed { "PASS" } else { "FAIL: expected " + i64_to_str(expected) + " got " + i64_to_str(actual) },
        };
    }

    func assert_eq_str(actual: string, expected: string, name: string) -> TestResult {
        let passed = actual == expected;
        return TestResult{
            name:    name,
            passed:  passed,
            message: if passed { "PASS" } else { "FAIL: expected \"" + expected + "\" got \"" + actual + "\"" },
        };
    }

    func print_result(r: TestResult) {
        let status = if r.passed { "[PASS]" } else { "[FAIL]" };
        print(status + " " + r.name + " - " + r.message);
    }

    // === 공통 스키마: users 테이블 ===
    // 컬럼: id(INT), name(STR), age(INT), active(BOOL)
    // INT 컬럼 순서: id=int_vals[0], age=int_vals[1]
    // STR 컬럼 순서: name=str_vals[0]
    // BOOL 컬럼 순서: active=bool_vals[0]

    func make_users_schema() -> schema.TableSchema {
        let s = schema.schema_new("users");
        s.schema_add_col("id",     schema.COL_TYPE_INT,  false);
        s.schema_add_col("name",   schema.COL_TYPE_STR,  false);
        s.schema_add_col("age",    schema.COL_TYPE_INT,  true);
        s.schema_add_col("active", schema.COL_TYPE_BOOL, false);
        return s;
    }

    func make_user_row(id: i64, name: string, age: i64, active: bool) -> schema.RecordRow {
        let row = schema.record_new();
        row.int_vals[0] = id;
        row.int_vals[1] = age;
        row.str_vals[0] = name;
        row.bool_vals[0] = active;
        return row;
    }

    // === 테스트 1: 스키마 + 테이블 기본 CRUD ===

    func test_schema_crud() {
        print("\n=== Test 1: Schema & Table CRUD ===");

        let s = make_users_schema();

        // 스키마 검증
        let r1 = assert_eq_i32(s.col_count, 4, "schema col_count == 4");
        print_result(r1);

        let col_idx, found = s.schema_find_col("age");
        let r2 = assert_true(found && col_idx == 2, "schema_find_col 'age' == 2");
        print_result(r2);

        // 테이블 생성
        let t = schema.table_new(s);
        let r3 = assert_eq_i32(t.row_count, 0, "initial row_count == 0");
        print_result(r3);

        // 행 삽입
        let row1 = make_user_row(1, "Alice", 30, true);
        let id1, ok1 = t.table_insert(row1);
        let r4 = assert_true(ok1 && id1 == 1, "insert Alice id == 1");
        print_result(r4);

        let row2 = make_user_row(2, "Bob", 25, false);
        let id2, ok2 = t.table_insert(row2);
        let r5 = assert_true(ok2 && id2 == 2, "insert Bob id == 2");
        print_result(r5);

        let row3 = make_user_row(3, "Charlie", 35, true);
        let id3, ok3 = t.table_insert(row3);
        let r6 = assert_true(ok3, "insert Charlie ok");
        print_result(r6);

        let r7 = assert_eq_i32(t.row_count, 3, "row_count == 3");
        print_result(r7);

        // 조회
        let fetched, ok4 = t.table_get(id1);
        let r8 = assert_true(ok4, "table_get Alice ok");
        print_result(r8);

        let r9 = assert_eq_str(fetched.str_vals[0], "Alice", "Alice name");
        print_result(r9);

        let r10 = assert_eq_i64(fetched.int_vals[1], 30, "Alice age == 30");
        print_result(r10);

        // 업데이트
        t.table_update_int(id1, 2, 31);  // age 컬럼(idx=2)
        let fetched2, ok5 = t.table_get(id1);
        let r11 = assert_eq_i64(fetched2.int_vals[1], 31, "Alice age updated to 31");
        print_result(r11);

        // 소프트 삭제
        t.table_delete(id2);
        let r12 = assert_eq_i32(t.table_count(), 2, "count == 2 after delete");
        print_result(r12);

        let _, ok6 = t.table_get(id2);
        let r13 = assert_true(!ok6, "deleted Bob not found");
        print_result(r13);

        print("Schema CRUD tests completed");
    }

    // === 테스트 2: 복합 쿼리 (WHERE + ORDER BY + LIMIT) ===

    func test_query_engine() {
        print("\n=== Test 2: Query Engine ===");

        let s = make_users_schema();
        let t = schema.table_new(s);

        // 10개 행 삽입
        let i = 0;
        for i = 0; i < 10; i = i + 1 {
            let row = make_user_row(
                i64(i + 1),
                "user_" + i32_to_str(i),
                i64(20 + i * 2),
                i % 2 == 0
            );
            t.table_insert(row);
        }

        // WHERE age > 25
        let q1 = query.query_table(t);
        q1.where_int(2, query.OP_GT, 25);
        let r1 = query.execute(t, q1);
        // age: 20,22,24,26,28,30,32,34,36,38 → >25 = 26,28,30,32,34,36,38 = 7개
        let res1 = assert_eq_i32(r1.row_count, 7, "WHERE age>25 count==7");
        print_result(res1);

        // WHERE age >= 20 AND age <= 30
        let q2 = query.query_table(t);
        q2.where_int(2, query.OP_GE, 20);
        q2.where_int(2, query.OP_LE, 30);
        let r2 = query.execute(t, q2);
        // age: 20,22,24,26,28,30 = 6개
        let res2 = assert_eq_i32(r2.row_count, 6, "WHERE 20<=age<=30 count==6");
        print_result(res2);

        // ORDER BY age DESC, LIMIT 3
        let q3 = query.query_table(t);
        q3.order_by_int(2, false);  // age DESC
        q3.set_limit(3);
        let r3 = query.execute(t, q3);
        let res3 = assert_eq_i32(r3.row_count, 3, "ORDER BY age DESC LIMIT 3 count==3");
        print_result(res3);

        // 첫 번째 결과가 가장 나이 많은 사람 (age=38)
        let top_row = t.table_get_row(r3.row_indices[0]);
        let res4 = assert_eq_i64(top_row.int_vals[1], 38, "DESC first row age==38");
        print_result(res4);

        // OFFSET + LIMIT (페이지 2)
        let q4 = query.query_table(t);
        q4.order_by_int(2, true);   // age ASC
        q4.set_offset(3);
        q4.set_limit(3);
        let r4 = query.execute(t, q4);
        let res5 = assert_eq_i32(r4.row_count, 3, "OFFSET 3 LIMIT 3 count==3");
        print_result(res5);

        // LIKE 쿼리: "user_1" 접두어 → "user_1" 1개
        let q5 = query.query_table(t);
        q5.where_str(1, query.OP_LIKE, "user_1");
        let r5 = query.execute(t, q5);
        let res6 = assert_true(r5.row_count >= 1, "LIKE 'user_1' count>=1");
        print_result(res6);

        print("Query engine tests completed");
    }

    // === 테스트 3: 집계 함수 ===

    func test_aggregation() {
        print("\n=== Test 3: Aggregation ===");

        let s = make_users_schema();
        let t = schema.table_new(s);

        // 5개 행 삽입 (age: 10, 20, 30, 40, 50)
        let i = 0;
        for i = 0; i < 5; i = i + 1 {
            let row = make_user_row(i64(i + 1), "user_" + i32_to_str(i), i64((i + 1) * 10), true);
            t.table_insert(row);
        }

        // COUNT
        let q1 = query.query_table(t);
        q1.set_aggregate(query.AGG_COUNT, 0);
        let r1 = query.execute(t, q1);
        let res1 = assert_eq_i64(r1.agg_value, 5, "COUNT == 5");
        print_result(res1);

        // SUM(age): 10+20+30+40+50 = 150
        let q2 = query.query_table(t);
        q2.set_aggregate(query.AGG_SUM, 2);  // age 컬럼(idx=2)
        let r2 = query.execute(t, q2);
        let res2 = assert_eq_i64(r2.agg_value, 150, "SUM(age) == 150");
        print_result(res2);

        // MAX(age) = 50
        let q3 = query.query_table(t);
        q3.set_aggregate(query.AGG_MAX, 2);
        let r3 = query.execute(t, q3);
        let res3 = assert_eq_i64(r3.agg_value, 50, "MAX(age) == 50");
        print_result(res3);

        // MIN(age) = 10
        let q4 = query.query_table(t);
        q4.set_aggregate(query.AGG_MIN, 2);
        let r4 = query.execute(t, q4);
        let res4 = assert_eq_i64(r4.agg_value, 10, "MIN(age) == 10");
        print_result(res4);

        // COUNT WHERE age > 20 → 30,40,50 = 3
        let q5 = query.query_table(t);
        q5.where_int(2, query.OP_GT, 20);
        q5.set_aggregate(query.AGG_COUNT, 0);
        let r5 = query.execute(t, q5);
        let res5 = assert_eq_i64(r5.agg_value, 3, "COUNT WHERE age>20 == 3");
        print_result(res5);

        print("Aggregation tests completed");
    }

    // === 테스트 4: ORM Repository ===

    func test_orm() {
        print("\n=== Test 4: ORM Repository ===");

        let s = make_users_schema();
        let repo = orm.repo_new(s);

        // INSERT
        let r1_row = make_user_row(1, "Alice", 30, true);
        let id1, ok1 = repo.repo_insert(r1_row);
        let t1 = assert_true(ok1, "orm insert Alice ok");
        print_result(t1);

        let r2_row = make_user_row(2, "Bob", 25, false);
        let id2, ok2 = repo.repo_insert(r2_row);

        let r3_row = make_user_row(3, "Charlie", 35, true);
        let id3, ok3 = repo.repo_insert(r3_row);

        // COUNT
        let t2 = assert_eq_i32(repo.repo_count(), 3, "orm count == 3");
        print_result(t2);

        // FIND BY ID
        let row, ok4 = repo.repo_find_by_id(id1);
        let t3 = assert_eq_str(row.str_vals[0], "Alice", "orm find Alice by id");
        print_result(t3);

        // FIND ALL
        let all = repo.repo_find_all();
        let t4 = assert_eq_i32(all.row_count, 3, "orm find_all count == 3");
        print_result(t4);

        // FIND WHERE
        let results = repo.repo_find_where_int(2, query.OP_GT, 28);  // age > 28
        let t5 = assert_eq_i32(results.row_count, 2, "orm find where age>28 == 2");
        print_result(t5);

        // UPDATE
        repo.repo_update_int(id1, 2, 31);  // age 컬럼(idx=2)
        let updated, ok5 = repo.repo_find_by_id(id1);
        let t6 = assert_eq_i64(updated.int_vals[1], 31, "orm update age == 31");
        print_result(t6);

        // UPDATE BY NAME
        let err, ok6 = repo.repo_update_by_name_str(id2, "name", "Robert");
        let t7 = assert_true(ok6, "orm update by name ok");
        print_result(t7);

        // SUM
        let sum_age = repo.repo_sum(2);  // age 컬럼
        let t8 = assert_eq_i64(sum_age, 91, "orm sum age == 91 (31+25+35)");
        print_result(t8);

        // MAX
        let max_age = repo.repo_max(2);
        let t9 = assert_eq_i64(max_age, 35, "orm max age == 35");
        print_result(t9);

        // DELETE
        repo.repo_delete(id2);
        let t10 = assert_eq_i32(repo.repo_count(), 2, "orm count after delete == 2");
        print_result(t10);

        // PAGING
        let page0 = repo.repo_page(0, 2);
        let t11 = assert_eq_i32(page0.row_count, 2, "orm page 0 count == 2");
        print_result(t11);

        print(repo.repo_stats());
        print("ORM tests completed");
    }

    // === 테스트 5: 트랜잭션 ===

    func test_transaction() {
        print("\n=== Test 5: Transaction COMMIT & ROLLBACK ===");

        let s = make_users_schema();
        let t = schema.table_new(s);

        // 시나리오 1: COMMIT
        let tx1 = transaction.tx_begin();
        let row1 = make_user_row(1, "Alice", 30, true);
        let id1, err1 = transaction.tx_insert(&tx1, &t, row1);
        let t1 = assert_true(err1 == transaction.TX_OK, "tx_insert ok");
        print_result(t1);

        transaction.tx_commit(&tx1);
        let t2 = assert_true(transaction.tx_is_committed(tx1), "tx committed");
        print_result(t2);

        let _, found1 = t.table_get(id1);
        let t3 = assert_true(found1, "committed row exists");
        print_result(t3);

        // 시나리오 2: ROLLBACK INSERT
        let tx2 = transaction.tx_begin();
        let row2 = make_user_row(2, "Bob", 25, false);
        let id2, err2 = transaction.tx_insert(&tx2, &t, row2);

        transaction.tx_rollback(&tx2, &t);
        let t4 = assert_true(transaction.tx_is_rolled_back(tx2), "tx2 rolled back");
        print_result(t4);

        let _, found2 = t.table_get(id2);
        let t5 = assert_true(!found2, "rolled back row not found");
        print_result(t5);

        // 시나리오 3: ROLLBACK UPDATE
        let tx3 = transaction.tx_begin();
        let err_upd = transaction.tx_update_int(&tx3, &t, id1, 2, 99);  // age → 99
        let t6 = assert_true(err_upd == transaction.TX_OK, "tx_update_int ok");
        print_result(t6);

        // 롤백 전 확인
        let before_rb, _ = t.table_get(id1);
        let t7 = assert_eq_i64(before_rb.int_vals[1], 99, "age==99 before rollback");
        print_result(t7);

        transaction.tx_rollback(&tx3, &t);

        // 롤백 후 확인 (age가 30으로 복구)
        let after_rb, _ = t.table_get(id1);
        let t8 = assert_eq_i64(after_rb.int_vals[1], 30, "age==30 after rollback");
        print_result(t8);

        // 시나리오 4: 비활성 트랜잭션 연산 거부
        let tx4 = transaction.tx_begin();
        transaction.tx_commit(&tx4);
        let row3 = make_user_row(3, "Charlie", 35, true);
        let _, err_after = transaction.tx_insert(&tx4, &t, row3);
        let t9 = assert_true(err_after == transaction.TX_ERR_NOT_ACTIVE, "committed tx rejects insert");
        print_result(t9);

        print(transaction.tx_stats(tx1));
        print(transaction.tx_stats(tx2));
        print("Transaction tests completed");
    }

    // === Main ===

    func main() {
        print("==========================================");
        print("FreeLang Phase 6 Query Engine Tests");
        print("==========================================");

        test_schema_crud();
        test_query_engine();
        test_aggregation();
        test_orm();
        test_transaction();

        print("\n==========================================");
        print("All query engine tests completed!");
        print("==========================================");
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_str(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n == 6 { return "6"; }
        if n == 7 { return "7"; }
        if n == 8 { return "8"; }
        if n == 9 { return "9"; }
        if n < 0 { return "-" + i32_to_str(-n); }
        let d = n / 10;
        let r = n % 10;
        return i32_to_str(d) + i32_to_str(r);
    }

    @inline
    func i64_to_str(n: i64) -> string {
        if n == 0 { return "0"; }
        if n < 0 { return "-" + i64_to_str(-n); }
        return i32_to_str(i32(n));
    }
}

// === 테스트 카테고리 정리 ===
//
// Test 1: Schema & Table CRUD (13개 검증)
//   ✓ schema_new + schema_add_col
//   ✓ schema_find_col
//   ✓ table_new + table_insert
//   ✓ table_get
//   ✓ table_update_int
//   ✓ table_delete (소프트)
//   ✓ table_count
//
// Test 2: Query Engine (6개 검증)
//   ✓ WHERE int (단일/복합)
//   ✓ ORDER BY DESC
//   ✓ LIMIT
//   ✓ OFFSET + LIMIT (페이징)
//   ✓ WHERE str LIKE
//
// Test 3: Aggregation (5개 검증)
//   ✓ COUNT
//   ✓ SUM
//   ✓ MAX
//   ✓ MIN
//   ✓ COUNT + WHERE
//
// Test 4: ORM Repository (11개 검증)
//   ✓ repo_insert
//   ✓ repo_count
//   ✓ repo_find_by_id
//   ✓ repo_find_all
//   ✓ repo_find_where_int
//   ✓ repo_update_int / repo_update_by_name_str
//   ✓ repo_sum / repo_max
//   ✓ repo_delete
//   ✓ repo_page
//
// Test 5: Transaction (9개 검증)
//   ✓ tx_begin + tx_insert + tx_commit
//   ✓ rollback INSERT
//   ✓ rollback UPDATE_INT (스냅샷 복구)
//   ✓ 비활성 트랜잭션 거부
//

toolUseResult.content:
// ============================================================================
// FreeLang 쿼리 엔진 통합 테스트 - Phase 6
// ============================================================================
// 범위: schema, query, orm, transaction 4개 모듈 통합 검증
// 시나리오:
//   1. 스키마 생성 + 테이블 CRUD
//   2. WHERE/ORDER BY/LIMIT/OFFSET 복합 쿼리
//   3. 집계 함수 (COUNT/SUM/MAX/MIN)
//   4. ORM Repository CRUD 전체 플로우
//   5. 트랜잭션 BEGIN/COMMIT/ROLLBACK
// ============================================================================

module query_test {
    // === 테스트 유틸리티 ===

    struct TestResult {
        name:    string;
        passed:  bool;
        message: string;
    }

    func assert_true(condition: bool, name: string) -> TestResult {
        return TestResult{
            name:    name,
            passed:  condition,
            message: if condition { "PASS" } else { "FAIL" },
        };
    }

    func assert_eq_i32(actual: i32, expected: i32, name: string) -> TestResult {
        let passed = actual == expected;
        return TestResult{
            name:    name,
            passed:  passed,
            message: if passed { "PASS" } else { "FAIL: expected " + i32_to_str(expected) + " got " + i32_to_str(actual) },
        };
    }

    func assert_eq_i64(actual: i64, expected: i64, name: string) -> TestResult {
        let passed = actual == expected;
        return TestResult{
            name:    name,
            passed:  passed,
            message: if passed { "PASS" } else { "FAIL: expected " + i64_to_str(expected) + " got " + i64_to_str(actual) },
        };
    }

    func assert_eq_str(actual: string, expected: string, name: string) -> TestResult {
        let passed = actual == expected;
        return TestResult{
            name:    name,
            passed:  passed,
            message: if passed { "PASS" } else { "FAIL: expected \"" + expected + "\" got \"" + actual + "\"" },
        };
    }

    func print_result(r: TestResult) {
        let status = if r.passed { "[PASS]" } else { "[FAIL]" };
        print(status + " " + r.name + " - " + r.message);
    }

    // === 공통 스키마: users 테이블 ===
    // 컬럼: id(INT), name(STR), age(INT), active(BOOL)
    // INT 컬럼 순서: id=int_vals[0], age=int_vals[1]
    // STR 컬럼 순서: name=str_vals[0]
    // BOOL 컬럼 순서: active=bool_vals[0]

    func make_users_schema() -> schema.TableSchema {
        let s = schema.schema_new("users");
        s.schema_add_col("id",     schema.COL_TYPE_INT,  false);
        s.schema_add_col("name",   schema.COL_TYPE_STR,  false);
        s.schema_add_col("age",    schema.COL_TYPE_INT,  true);
        s.schema_add_col("active", schema.COL_TYPE_BOOL, false);
        return s;
    }

    func make_user_row(id: i64, name: string, age: i64, active: bool) -> schema.RecordRow {
        let row = schema.record_new();
        row.int_vals[0] = id;
        row.int_vals[1] = age;
        row.str_vals[0] = name;
        row.bool_vals[0] = active;
        return row;
    }

    // === 테스트 1: 스키마 + 테이블 기본 CRUD ===

    func test_schema_crud() {
        print("\n=== Test 1: Schema & Table CRUD ===");

        let s = make_users_schema();

        // 스키마 검증
        let r1 = assert_eq_i32(s.col_count, 4, "schema col_count == 4");
        print_result(r1);

        let col_idx, found = s.schema_find_col("age");
        let r2 = assert_true(found && col_idx == 2, "schema_find_col 'age' == 2");
        print_result(r2);

        // 테이블 생성
        let t = schema.table_new(s);
        let r3 = assert_eq_i32(t.row_count, 0, "initial row_count == 0");
        print_result(r3);

        // 행 삽입
        let row1 = make_user_row(1, "Alice", 30, true);
        let id1, ok1 = t.table_insert(row1);
        let r4 = assert_true(ok1 && id1 == 1, "insert Alice id == 1");
        print_result(r4);

        let row2 = make_user_row(2, "Bob", 25, false);
        let id2, ok2 = t.table_insert(row2);
        let r5 = assert_true(ok2 && id2 == 2, "insert Bob id == 2");
        print_result(r5);

        let row3 = make_user_row(3, "Charlie", 35, true);
        let id3, ok3 = t.table_insert(row3);
        let r6 = assert_true(ok3, "insert Charlie ok");
        print_result(r6);

        let r7 = assert_eq_i32(t.row_count, 3, "row_count == 3");
        print_result(r7);

        // 조회
        let fetched, ok4 = t.table_get(id1);
        let r8 = assert_true(ok4, "table_get Alice ok");
        print_result(r8);

        let r9 = assert_eq_str(fetched.str_vals[0], "Alice", "Alice name");
        print_result(r9);

        let r10 = assert_eq_i64(fetched.int_vals[1], 30, "Alice age == 30");
        print_result(r10);

        // 업데이트
        t.table_update_int(id1, 2, 31);  // age 컬럼(idx=2)
        let fetched2, ok5 = t.table_get(id1);
        let r11 = assert_eq_i64(fetched2.int_vals[1], 31, "Alice age updated to 31");
        print_result(r11);

        // 소프트 삭제
        t.table_delete(id2);
        let r12 = assert_eq_i32(t.table_count(), 2, "count == 2 after delete");
        print_result(r12);

        let _, ok6 = t.table_get(id2);
        let r13 = assert_true(!ok6, "deleted Bob not found");
        print_result(r13);

        print("Schema CRUD tests completed");
    }

    // === 테스트 2: 복합 쿼리 (WHERE + ORDER BY + LIMIT) ===

    func test_query_engine() {
        print("\n=== Test 2: Query Engine ===");

        let s = make_users_schema();
        let t = schema.table_new(s);

        // 10개 행 삽입
        let i = 0;
        for i = 0; i < 10; i = i + 1 {
            let row = make_user_row(
                i64(i + 1),
                "user_" + i32_to_str(i),
                i64(20 + i * 2),
                i % 2 == 0
            );
            t.table_insert(row);
        }

        // WHERE age > 25
        let q1 = query.query_table(t);
        q1.where_int(2, query.OP_GT, 25);
        let r1 = query.execute(t, q1);
        // age: 20,22,24,26,28,30,32,34,36,38 → >25 = 26,28,30,32,34,36,38 = 7개
        let res1 = assert_eq_i32(r1.row_count, 7, "WHERE age>25 count==7");
        print_result(res1);

        // WHERE age >= 20 AND age <= 30
        let q2 = query.query_table(t);
        q2.where_int(2, query.OP_GE, 20);
        q2.where_int(2, query.OP_LE, 30);
        let r2 = query.execute(t, q2);
        // age: 20,22,24,26,28,30 = 6개
        let res2 = assert_eq_i32(r2.row_count, 6, "WHERE 20<=age<=30 count==6");
        print_result(res2);

        // ORDER BY age DESC, LIMIT 3
        let q3 = query.query_table(t);
        q3.order_by_int(2, false);  // age DESC
        q3.set_limit(3);
        let r3 = query.execute(t, q3);
        let res3 = assert_eq_i32(r3.row_count, 3, "ORDER BY age DESC LIMIT 3 count==3");
        print_result(res3);

        // 첫 번째 결과가 가장 나이 많은 사람 (age=38)
        let top_row = t.table_get_row(r3.row_indices[0]);
        let res4 = assert_eq_i64(top_row.int_vals[1], 38, "DESC first row age==38");
        print_result(res4);

        // OFFSET + LIMIT (페이지 2)
        let q4 = query.query_table(t);
        q4.order_by_int(2, true);   // age ASC
        q4.set_offset(3);
        q4.set_limit(3);
        let r4 = query.execute(t, q4);
        let res5 = assert_eq_i32(r4.row_count, 3, "OFFSET 3 LIMIT 3 count==3");
        print_result(res5);

        // LIKE 쿼리: "user_1" 접두어 → "user_1" 1개
        let q5 = query.query_table(t);
        q5.where_str(1, query.OP_LIKE, "user_1");
        let r5 = query.execute(t, q5);
        let res6 = assert_true(r5.row_count >= 1, "LIKE 'user_1' count>=1");
        print_result(res6);

        print("Query engine tests completed");
    }

    // === 테스트 3: 집계 함수 ===

    func test_aggregation() {
        print("\n=== Test 3: Aggregation ===");

        let s = make_users_schema();
        let t = schema.table_new(s);

        // 5개 행 삽입 (age: 10, 20, 30, 40, 50)
        let i = 0;
        for i = 0; i < 5; i = i + 1 {
            let row = make_user_row(i64(i + 1), "user_" + i32_to_str(i), i64((i + 1) * 10), true);
            t.table_insert(row);
        }

        // COUNT
        let q1 = query.query_table(t);
        q1.set_aggregate(query.AGG_COUNT, 0);
        let r1 = query.execute(t, q1);
        let res1 = assert_eq_i64(r1.agg_value, 5, "COUNT == 5");
        print_result(res1);

        // SUM(age): 10+20+30+40+50 = 150
        let q2 = query.query_table(t);
        q2.set_aggregate(query.AGG_SUM, 2);  // age 컬럼(idx=2)
        let r2 = query.execute(t, q2);
        let res2 = assert_eq_i64(r2.agg_value, 150, "SUM(age) == 150");
        print_result(res2);

        // MAX(age) = 50
        let q3 = query.query_table(t);
        q3.set_aggregate(query.AGG_MAX, 2);
        let r3 = query.execute(t, q3);
        let res3 = assert_eq_i64(r3.agg_value, 50, "MAX(age) == 50");
        print_result(res3);

        // MIN(age) = 10
        let q4 = query.query_table(t);
        q4.set_aggregate(query.AGG_MIN, 2);
        let r4 = query.execute(t, q4);
        let res4 = assert_eq_i64(r4.agg_value, 10, "MIN(age) == 10");
        print_result(res4);

        // COUNT WHERE age > 20 → 30,40,50 = 3
        let q5 = query.query_table(t);
        q5.where_int(2, query.OP_GT, 20);
        q5.set_aggregate(query.AGG_COUNT, 0);
        let r5 = query.execute(t, q5);
        let res5 = assert_eq_i64(r5.agg_value, 3, "COUNT WHERE age>20 == 3");
        print_result(res5);

        print("Aggregation tests completed");
    }

    // === 테스트 4: ORM Repository ===

    func test_orm() {
        print("\n=== Test 4: ORM Repository ===");

        let s = make_users_schema();
        let repo = orm.repo_new(s);

        // INSERT
        let r1_row = make_user_row(1, "Alice", 30, true);
        let id1, ok1 = repo.repo_insert(r1_row);
        let t1 = assert_true(ok1, "orm insert Alice ok");
        print_result(t1);

        let r2_row = make_user_row(2, "Bob", 25, false);
        let id2, ok2 = repo.repo_insert(r2_row);

        let r3_row = make_user_row(3, "Charlie", 35, true);
        let id3, ok3 = repo.repo_insert(r3_row);

        // COUNT
        let t2 = assert_eq_i32(repo.repo_count(), 3, "orm count == 3");
        print_result(t2);

        // FIND BY ID
        let row, ok4 = repo.repo_find_by_id(id1);
        let t3 = assert_eq_str(row.str_vals[0], "Alice", "orm find Alice by id");
        print_result(t3);

        // FIND ALL
        let all = repo.repo_find_all();
        let t4 = assert_eq_i32(all.row_count, 3, "orm find_all count == 3");
        print_result(t4);

        // FIND WHERE
        let results = repo.repo_find_where_int(2, query.OP_GT, 28);  // age > 28
        let t5 = assert_eq_i32(results.row_count, 2, "orm find where age>28 == 2");
        print_result(t5);

        // UPDATE
        repo.repo_update_int(id1, 2, 31);  // age 컬럼(idx=2)
        let updated, ok5 = repo.repo_find_by_id(id1);
        let t6 = assert_eq_i64(updated.int_vals[1], 31, "orm update age == 31");
        print_result(t6);

        // UPDATE BY NAME
        let err, ok6 = repo.repo_update_by_name_str(id2, "name", "Robert");
        let t7 = assert_true(ok6, "orm update by name ok");
        print_result(t7);

        // SUM
        let sum_age = repo.repo_sum(2);  // age 컬럼
        let t8 = assert_eq_i64(sum_age, 91, "orm sum age == 91 (31+25+35)");
        print_result(t8);

        // MAX
        let max_age = repo.repo_max(2);
        let t9 = assert_eq_i64(max_age, 35, "orm max age == 35");
        print_result(t9);

        // DELETE
        repo.repo_delete(id2);
        let t10 = assert_eq_i32(repo.repo_count(), 2, "orm count after delete == 2");
        print_result(t10);

        // PAGING
        let page0 = repo.repo_page(0, 2);
        let t11 = assert_eq_i32(page0.row_count, 2, "orm page 0 count == 2");
        print_result(t11);

        print(repo.repo_stats());
        print("ORM tests completed");
    }

    // === 테스트 5: 트랜잭션 ===

    func test_transaction() {
        print("\n=== Test 5: Transaction COMMIT & ROLLBACK ===");

        let s = make_users_schema();
        let t = schema.table_new(s);

        // 시나리오 1: COMMIT
        let tx1 = transaction.tx_begin();
        let row1 = make_user_row(1, "Alice", 30, true);
        let id1, err1 = transaction.tx_insert(&tx1, &t, row1);
        let t1 = assert_true(err1 == transaction.TX_OK, "tx_insert ok");
        print_result(t1);

        transaction.tx_commit(&tx1);
        let t2 = assert_true(transaction.tx_is_committed(tx1), "tx committed");
        print_result(t2);

        let _, found1 = t.table_get(id1);
        let t3 = assert_true(found1, "committed row exists");
        print_result(t3);

        // 시나리오 2: ROLLBACK INSERT
        let tx2 = transaction.tx_begin();
        let row2 = make_user_row(2, "Bob", 25, false);
        let id2, err2 = transaction.tx_insert(&tx2, &t, row2);

        transaction.tx_rollback(&tx2, &t);
        let t4 = assert_true(transaction.tx_is_rolled_back(tx2), "tx2 rolled back");
        print_result(t4);

        let _, found2 = t.table_get(id2);
        let t5 = assert_true(!found2, "rolled back row not found");
        print_result(t5);

        // 시나리오 3: ROLLBACK UPDATE
        let tx3 = transaction.tx_begin();
        let err_upd = transaction.tx_update_int(&tx3, &t, id1, 2, 99);  // age → 99
        let t6 = assert_true(err_upd == transaction.TX_OK, "tx_update_int ok");
        print_result(t6);

        // 롤백 전 확인
        let before_rb, _ = t.table_get(id1);
        let t7 = assert_eq_i64(before_rb.int_vals[1], 99, "age==99 before rollback");
        print_result(t7);

        transaction.tx_rollback(&tx3, &t);

        // 롤백 후 확인 (age가 30으로 복구)
        let after_rb, _ = t.table_get(id1);
        let t8 = assert_eq_i64(after_rb.int_vals[1], 30, "age==30 after rollback");
        print_result(t8);

        // 시나리오 4: 비활성 트랜잭션 연산 거부
        let tx4 = transaction.tx_begin();
        transaction.tx_commit(&tx4);
        let row3 = make_user_row(3, "Charlie", 35, true);
        let _, err_after = transaction.tx_insert(&tx4, &t, row3);
        let t9 = assert_true(err_after == transaction.TX_ERR_NOT_ACTIVE, "committed tx rejects insert");
        print_result(t9);

        print(transaction.tx_stats(tx1));
        print(transaction.tx_stats(tx2));
        print("Transaction tests completed");
    }

    // === Main ===

    func main() {
        print("==========================================");
        print("FreeLang Phase 6 Query Engine Tests");
        print("==========================================");

        test_schema_crud();
        test_query_engine();
        test_aggregation();
        test_orm();
        test_transaction();

        print("\n==========================================");
        print("All query engine tests completed!");
        print("==========================================");
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_str(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n == 6 { return "6"; }
        if n == 7 { return "7"; }
        if n == 8 { return "8"; }
        if n == 9 { return "9"; }
        if n < 0 { return "-" + i32_to_str(-n); }
        let d = n / 10;
        let r = n % 10;
        return i32_to_str(d) + i32_to_str(r);
    }

    @inline
    func i64_to_str(n: i64) -> string {
        if n == 0 { return "0"; }
        if n < 0 { return "-" + i64_to_str(-n); }
        return i32_to_str(i32(n));
    }
}

