// ============================================================================
// FreeLang 인덱스 통합 테스트 - Phase 7
// ============================================================================
// 범위: index, index_str, planner 3개 모듈 통합 검증
// 시나리오:
//   1. B+Tree 기본 (삽입/검색/삭제)
//   2. 범위 스캔 (1000개 키 → 범위 쿼리)
//   3. 문자열 인덱스 (LIKE 검색)
//   4. 플래너 비용 추정 (EQ vs 풀스캔)
//   5. 통합 (schema + index + planner)
// ============================================================================

module index_test {
    // === 테스트 유틸리티 ===

    struct TestResult {
        name:    string;
        passed:  bool;
        message: string;
    }

    func assert_true(condition: bool, name: string) -> TestResult {
        return TestResult{
            name:    name,
            passed:  condition,
            message: if condition { "PASS" } else { "FAIL" },
        };
    }

    func assert_eq_i32(actual: i32, expected: i32, name: string) -> TestResult {
        let passed = actual == expected;
        return TestResult{
            name:    name,
            passed:  passed,
            message: if passed { "PASS" } else { "FAIL: expected " + i32_to_str(expected) + " got " + i32_to_str(actual) },
        };
    }

    func assert_eq_i64(actual: i64, expected: i64, name: string) -> TestResult {
        let passed = actual == expected;
        return TestResult{
            name:    name,
            passed:  passed,
            message: if passed { "PASS" } else { "FAIL: expected " + i64_to_str(expected) + " got " + i64_to_str(actual) },
        };
    }

    func print_result(r: TestResult) {
        let status = if r.passed { "[PASS]" } else { "[FAIL]" };
        print(status + " " + r.name + " - " + r.message);
    }

    // === 테스트 1: B+Tree 기본 ===

    func test_btree_basic() {
        print("\n=== Test 1: B+Tree Basic Operations ===");

        let idx = index.index_new(0);  // col_idx=0

        // 삽입
        let err1 = idx.index_insert(100, 1);
        let t1 = assert_eq_i32(err1, index.IDX_OK, "insert 100→1 ok");
        print_result(t1);

        let err2 = idx.index_insert(50, 2);
        let t2 = assert_eq_i32(err2, index.IDX_OK, "insert 50→2 ok");
        print_result(t2);

        let err3 = idx.index_insert(150, 3);
        let t3 = assert_eq_i32(err3, index.IDX_OK, "insert 150→3 ok");
        print_result(t3);

        // EQ 검색
        let row_id, found1 = idx.index_search(100);
        let t4 = assert_true(found1 && row_id == 1, "search 100 → row_id=1");
        print_result(t4);

        let row_id2, found2 = idx.index_search(50);
        let t5 = assert_true(found2 && row_id2 == 2, "search 50 → row_id=2");
        print_result(t5);

        // 검색 실패
        let _, found3 = idx.index_search(999);
        let t6 = assert_true(!found3, "search 999 → not found");
        print_result(t6);

        // 삭제
        let del_ok = idx.index_delete(50, 2);
        let t7 = assert_true(del_ok, "delete 50→2 ok");
        print_result(t7);

        let _, found4 = idx.index_search(50);
        let t8 = assert_true(!found4, "search 50 after delete → not found");
        print_result(t8);

        print(idx.index_stats());
    }

    // === 테스트 2: 범위 스캔 ===

    func test_range_scan() {
        print("\n=== Test 2: Range Scan ===");

        let idx = index.index_new(0);

        // 100개 키 삽입 (10, 20, 30, ..., 1000)
        let i = 0;
        for i = 0; i < 100; i = i + 1 {
            let key = i64((i + 1) * 10);
            let err = idx.index_insert(key, i64(i + 1));
            if err != index.IDX_OK {
                break;
            }
        }

        let t1 = assert_eq_i32(idx.key_count, 100, "inserted 100 keys");
        print_result(t1);

        // 범위 스캔: 100 <= key <= 300 (10개: 100,110,...,300)
        let result, count = idx.index_range(100, 300);
        let t2 = assert_eq_i32(count, 21, "range [100,300] count=21");
        print_result(t2);

        // 범위 스캔: 500 <= key <= 700 (21개: 500,510,...,700)
        let result2, count2 = idx.index_range(500, 700);
        let t3 = assert_eq_i32(count2, 21, "range [500,700] count=21");
        print_result(t3);

        print("Range scan tests completed");
