// ============================================================================
// FreeLang Planner 모듈 - 비용 기반 쿼리 실행 계획
// ============================================================================
// 목표: WHERE 절 기반으로 최적의 실행 경로 선택
// 원리:
//   1. 테이블 통계: row_count, 컬럼 min/max
//   2. 비용 추정: 풀스캔 O(n), 인덱스 범위 O(log n + k)
//   3. 계획 선택: 비용이 낮은 경로 선택
// 구조:
//   - TableStats, ExecPlan 구조체
//   - 통계 수집 (stats_build, stats_update)
//   - 계획 생성 (plan_query)
// ============================================================================

module planner {
    // === 계획 타입 ===
    const PLAN_FULL_SCAN:   i32 = 1;
    const PLAN_INDEX_EQ:    i32 = 2;
    const PLAN_INDEX_RANGE: i32 = 3;
    const PLAN_INDEX_LIKE:  i32 = 4;

    // === 데이터 구조체 ===

    struct TableStats {
        row_count:    i32;
        col_count:    i32;
        col_min:      [i64];   // 각 컬럼별 MIN
        col_max:      [i64];   // 각 컬럼별 MAX
        col_null_cnt: [i32];   // NULL 수
    }

    struct ExecPlan {
        plan_type:  i32;   // PLAN_*
        index_col:  i32;   // 사용할 인덱스 컬럼 (-1 = 없음)
        est_rows:   i32;   // 예상 결과 행 수
        cost:       i32;   // 비용 추정치
    }

    // === 통계 수집 ===

    func stats_build(t: schema.Table) -> TableStats {
        let stats = TableStats{
            row_count:    t.table_count(),
            col_count:    t.schema.col_count,
            col_min:      make([i64], 16),
            col_max:      make([i64], 16),
            col_null_cnt: make([i32], 16),
        };

        // 각 컬럼별 MIN/MAX 계산
        let col_idx = 0;
        for col_idx = 0; col_idx < stats.col_count; col_idx = col_idx + 1 {
            let col_type = t.schema.col_defs[col_idx].col_type;

            if col_type == schema.COL_TYPE_INT {
                // INT 컬럼: 첫 번째 non-null 값으로 min/max 초기화
                let found_first = false;
                let i = 0;
                for i = 0; i < t.row_count; i = i + 1 {
                    if !t.deleted_flags[i] {
                        let val = t.get_int_val(i, col_idx);
                        if !found_first {
                            stats.col_min[col_idx] = val;
                            stats.col_max[col_idx] = val;
                            found_first = true;
                        } else {
                            if val < stats.col_min[col_idx] {
                                stats.col_min[col_idx] = val;
                            }
                            if val > stats.col_max[col_idx] {
                                stats.col_max[col_idx] = val;
                            }
                        }
                    }
                }
            }
        }

        return stats;
    }

    // === 계획 생성 ===

    func plan_query(q: query.Query, stats: TableStats, has_int_idx: bool, has_str_idx: bool) -> ExecPlan {
        // 기본: 풀스캔
        let plan = ExecPlan{
            plan_type:  PLAN_FULL_SCAN,
            index_col:  -1,
            est_rows:   stats.row_count,
            cost:       stats.row_count,
        };

        // WHERE 절이 단일 조건인 경우만 인덱스 고려
        if q.where_count != 1 {
            return plan;  // 복합 조건은 풀스캔
        }

        let where_clause = q.wheres[0];
        let col_idx = where_clause.col_idx;

        // INT 인덱스 사용 가능 여부
        if has_int_idx && q.wheres[0].is_str == false {
            if where_clause.op == query.OP_EQ {
                // EQ: log(n) + 1 (최악 1행)
                plan.plan_type = PLAN_INDEX_EQ;
                plan.index_col = col_idx;
                plan.est_rows = 1;
                plan.cost = log_cost(stats.row_count);
                return plan;
            } else if where_clause.op == query.OP_GT || where_clause.op == query.OP_LT ||
                      where_clause.op == query.OP_GE || where_clause.op == query.OP_LE {
                // RANGE: log(n) + 범위 크기 추정
                let range_est = range_estimate(stats, col_idx, where_clause.op, where_clause.int_val);
                plan.plan_type = PLAN_INDEX_RANGE;
                plan.index_col = col_idx;
                plan.est_rows = range_est;
                plan.cost = log_cost(stats.row_count) + range_est;
                return plan;
            }
        }

        // STR 인덱스 사용 가능 여부
        if has_str_idx && q.wheres[0].is_str == true {
            if where_clause.op == query.OP_LIKE {
                // LIKE: 접두어 길이에 따라 추정 (간단화: row_count/10)
                plan.plan_type = PLAN_INDEX_LIKE;
                plan.index_col = col_idx;
                plan.est_rows = stats.row_count / 10;
                plan.cost = log_cost(stats.row_count) + plan.est_rows;
                return plan;
            }
        }

        return plan;  // 기본: 풀스캔
    }

    // === 비용 추정 헬퍼 함수 ===

    @inline
    func log_cost(n: i32) -> i32 {
        // log(n) 근사: 비트 길이 (대략)
        if n <= 1 { return 0; }
        if n <= 2 { return 1; }
        if n <= 4 { return 2; }
        if n <= 8 { return 3; }
        if n <= 16 { return 4; }
        if n <= 32 { return 5; }
        if n <= 64 { return 6; }
        if n <= 128 { return 7; }
        if n <= 256 { return 8; }
        if n <= 512 { return 9; }
        if n <= 1024 { return 10; }
        return 11;
    }

    func range_estimate(stats: TableStats, col_idx: i32, op: i32, value: i64) -> i32 {
        // 범위 크기 추정 (간단화: 전체의 1/4 ~ 1/2)
        let col_min = stats.col_min[col_idx];
        let col_max = stats.col_max[col_idx];
        let col_range = col_max - col_min;

        if col_range == 0 {
            return stats.row_count;
        }

        if op == query.OP_GT {
            // value < col <= col_max
            let dist = (col_max - value) * 100 / col_range;
            return (stats.row_count * dist) / 100;
        } else if op == query.OP_LT {
            // col_min <= col < value
            let dist = (value - col_min) * 100 / col_range;
            return (stats.row_count * dist) / 100;
        } else if op == query.OP_GE {
            // value <= col <= col_max
            let dist = (col_max - value) * 100 / col_range;
            return (stats.row_count * dist) / 100 + 1;
        } else if op == query.OP_LE {
            // col_min <= col <= value
            let dist = (value - col_min) * 100 / col_range;
            return (stats.row_count * dist) / 100 + 1;
        }

        return stats.row_count / 4;
    }

    // === 계획 기반 실행 (간단화) ===

    // 계획에 따라 쿼리 실행 (선택적)
    func execute_planned(t: schema.Table, q: query.Query,
        plan: ExecPlan, idx: index.BTreeIndex, si: index_str.StrIndex) -> query.QueryResult {
        // PLAN_FULL_SCAN: 기존 query.execute 사용
        if plan.plan_type == PLAN_FULL_SCAN {
            return query.execute(t, q);
        }

        // PLAN_INDEX_EQ: 인덱스에서 row_id 찾고, query.QueryResult 반환
        if plan.plan_type == PLAN_INDEX_EQ {
            let val = q.wheres[0].int_val;
            let row_id, found = idx.index_search(val);
            let result = query.QueryResult{
                row_indices: make([i32], 1024),
                row_count:   0,
                agg_value:   0,
                error_code:  0,
            };
            if found {
                let row_idx, found2 = t.find_row_idx(row_id);
                if found2 {
                    result.row_indices[0] = row_idx;
                    result.row_count = 1;
                }
            }
            return result;
        }

        // PLAN_INDEX_RANGE: 범위 스캔
        if plan.plan_type == PLAN_INDEX_RANGE {
            let min_val = q.wheres[0].int_val;
            let max_val = min_val + 100;  // 범위 추정 (간단화)
            let row_ids, count = idx.index_range(min_val, max_val);
            let result = query.QueryResult{
                row_indices: make([i32], 1024),
                row_count:   0,
                agg_value:   0,
                error_code:  0,
            };
            let i = 0;
            for i = 0; i < count && i < 1024; i = i + 1 {
                let row_idx, found = t.find_row_idx(row_ids[i]);
                if found {
                    result.row_indices[result.row_count] = row_idx;
                    result.row_count = result.row_count + 1;
                }
            }
            return result;
        }

        // PLAN_INDEX_LIKE: 문자열 인덱스
        if plan.plan_type == PLAN_INDEX_LIKE {
            let prefix = q.wheres[0].str_val;
            let row_ids, count = si.str_like(prefix);
            let result = query.QueryResult{
                row_indices: make([i32], 1024),
                row_count:   0,
                agg_value:   0,
                error_code:  0,
            };
            let i = 0;
            for i = 0; i < count && i < 1024; i = i + 1 {
                let row_idx, found = t.find_row_idx(row_ids[i]);
                if found {
                    result.row_indices[result.row_count] = row_idx;
                    result.row_count = result.row_count + 1;
                }
            }
            return result;
        }

        // 기본: 풀스캔
        return query.execute(t, q);
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_str(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n < 0 { return "-" + i32_to_str(-n); }
        return "?";
    }
}

