// ============================================================================
// FreeLang 인덱스 통합 테스트 - Phase 7
// ============================================================================
// 범위: index, index_str, planner 3개 모듈 통합 검증
// 시나리오:
//   1. B+Tree 기본 (삽입/검색/삭제)
//   2. 범위 스캔 (1000개 키 → 범위 쿼리)
//   3. 문자열 인덱스 (LIKE 검색)
//   4. 플래너 비용 추정 (EQ vs 풀스캔)
//   5. 통합 (schema + index + planner)
// ============================================================================

module index_test {
    // === 테스트 유틸리티 ===

    struct TestResult {
        name:    string;
        passed:  bool;
        message: string;
    }

    func assert_true(condition: bool, name: string) -> TestResult {
        return TestResult{
            name:    name,
            passed:  condition,
            message: if condition { "PASS" } else { "FAIL" },
        };
    }

    func assert_eq_i32(actual: i32, expected: i32, name: string) -> TestResult {
        let passed = actual == expected;
        return TestResult{
            name:    name,
            passed:  passed,
            message: if passed { "PASS" } else { "FAIL: expected " + i32_to_str(expected) + " got " + i32_to_str(actual) },
        };
    }

    func assert_eq_i64(actual: i64, expected: i64, name: string) -> TestResult {
        let passed = actual == expected;
        return TestResult{
            name:    name,
            passed:  passed,
            message: if passed { "PASS" } else { "FAIL: expected " + i64_to_str(expected) + " got " + i64_to_str(actual) },
        };
    }

    func print_result(r: TestResult) {
        let status = if r.passed { "[PASS]" } else { "[FAIL]" };
        print(status + " " + r.name + " - " + r.message);
    }

    // === 테스트 1: B+Tree 기본 ===

    func test_btree_basic() {
        print("\n=== Test 1: B+Tree Basic Operations ===");

        let idx = index.index_new(0);  // col_idx=0

        // 삽입
        let err1 = idx.index_insert(100, 1);
        let t1 = assert_eq_i32(err1, index.IDX_OK, "insert 100→1 ok");
        print_result(t1);

        let err2 = idx.index_insert(50, 2);
        let t2 = assert_eq_i32(err2, index.IDX_OK, "insert 50→2 ok");
        print_result(t2);

        let err3 = idx.index_insert(150, 3);
        let t3 = assert_eq_i32(err3, index.IDX_OK, "insert 150→3 ok");
        print_result(t3);

        // EQ 검색
        let row_id, found1 = idx.index_search(100);
        let t4 = assert_true(found1 && row_id == 1, "search 100 → row_id=1");
        print_result(t4);

        let row_id2, found2 = idx.index_search(50);
        let t5 = assert_true(found2 && row_id2 == 2, "search 50 → row_id=2");
        print_result(t5);

        // 검색 실패
        let _, found3 = idx.index_search(999);
        let t6 = assert_true(!found3, "search 999 → not found");
        print_result(t6);

        // 삭제
        let del_ok = idx.index_delete(50, 2);
        let t7 = assert_true(del_ok, "delete 50→2 ok");
        print_result(t7);

        let _, found4 = idx.index_search(50);
        let t8 = assert_true(!found4, "search 50 after delete → not found");
        print_result(t8);

        print(idx.index_stats());
    }

    // === 테스트 2: 범위 스캔 ===

    func test_range_scan() {
        print("\n=== Test 2: Range Scan ===");

        let idx = index.index_new(0);

        // 100개 키 삽입 (10, 20, 30, ..., 1000)
        let i = 0;
        for i = 0; i < 100; i = i + 1 {
            let key = i64((i + 1) * 10);
            let err = idx.index_insert(key, i64(i + 1));
            if err != index.IDX_OK {
                break;
            }
        }

        let t1 = assert_eq_i32(idx.key_count, 100, "inserted 100 keys");
        print_result(t1);

        // 범위 스캔: 100 <= key <= 300 (10개: 100,110,...,300)
        let result, count = idx.index_range(100, 300);
        let t2 = assert_eq_i32(count, 21, "range [100,300] count=21");
        print_result(t2);

        // 범위 스캔: 500 <= key <= 700 (21개: 500,510,...,700)
        let result2, count2 = idx.index_range(500, 700);
        let t3 = assert_eq_i32(count2, 21, "range [500,700] count=21");
        print_result(t3);

        print("Range scan tests completed");
    }

    // === 테스트 3: 문자열 인덱스 ===

    func test_str_index() {
        print("\n=== Test 3: String Index ===");

        let si = index_str.str_index_new(1);  // col_idx=1

        // 삽입 (정렬 자동)
        let err1 = si.str_insert("alice", 1);
        let t1 = assert_eq_i32(err1, index_str.STR_IDX_OK, "insert alice ok");
        print_result(t1);

        let err2 = si.str_insert("bob", 2);
        let err3 = si.str_insert("charlie", 3);
        let err4 = si.str_insert("alicia", 4);

        let t2 = assert_eq_i32(si.entry_count, 4, "4 entries inserted");
        print_result(t2);

        // EQ 검색
        let row_id, found = si.str_search("bob");
        let t3 = assert_true(found && row_id == 2, "search bob → row_id=2");
        print_result(t3);

        // LIKE 검색
        let result, count = si.str_like("ali");
        // alice, alicia = 2개
        let t4 = assert_eq_i32(count, 2, "like 'ali' count=2");
        print_result(t4);

        // 범위 검색
        let result2, count2 = si.str_range("alice", "bob");
        // alice, alicia, bob = 3개
        let t5 = assert_eq_i32(count2, 3, "range [alice,bob] count=3");
        print_result(t5);

        // 삭제
        let del_ok = si.str_delete("bob", 2);
        let t6 = assert_true(del_ok, "delete bob ok");
        print_result(t6);

        let t7 = assert_eq_i32(si.entry_count, 3, "3 entries after delete");
        print_result(t7);

        print(si.str_stats());
    }

    // === 테스트 4: 플래너 비용 추정 ===

    func test_planner() {
        print("\n=== Test 4: Query Planner ===");

        // 스키마 + 테이블 생성
        let s = schema.schema_new("test");
        s.schema_add_col("id", schema.COL_TYPE_INT, false);
        s.schema_add_col("val", schema.COL_TYPE_INT, false);

        let t = schema.table_new(s);

        // 10개 행 삽입 (val: 10, 20, 30, ..., 100)
        let i = 0;
        for i = 0; i < 10; i = i + 1 {
            let row = schema.record_new();
            row.int_vals[0] = i64(i + 1);
            row.int_vals[1] = i64((i + 1) * 10);
            t.table_insert(row);
        }

        // 통계 수집
        let stats = planner.stats_build(&t);
        let t1 = assert_eq_i32(stats.row_count, 10, "stats row_count=10");
        print_result(t1);

        // 쿼리 생성
        let q = query.query_table(t);
        q.where_int(1, query.OP_EQ, 50);  // val == 50

        // 계획 생성 (인덱스 없음 → 풀스캔)
        let plan = planner.plan_query(&q, &stats, false, false);
        let t2 = assert_eq_i32(plan.plan_type, planner.PLAN_FULL_SCAN, "no index → full scan");
        print_result(t2);

        let t3 = assert_eq_i32(plan.cost, 10, "cost=10 (row_count)");
        print_result(t3);

        // 범위 쿼리
        let q2 = query.query_table(t);
        q2.where_int(1, query.OP_GT, 50);  // val > 50
        let plan2 = planner.plan_query(&q2, &stats, false, false);
        let t4 = assert_true(plan2.plan_type == planner.PLAN_FULL_SCAN, "range query → full scan");
        print_result(t4);

        print("Planner tests completed");
    }

    // === 테스트 5: 통합 (테이블 + 인덱스 + 플래너) ===

    func test_integration() {
        print("\n=== Test 5: Integration Test ===");

        // 스키마 생성
        let s = schema.schema_new("products");
        s.schema_add_col("id", schema.COL_TYPE_INT, false);
        s.schema_add_col("price", schema.COL_TYPE_INT, false);

        let t = schema.table_new(s);

        // 테이블에 데이터 삽입
        let i = 0;
        for i = 0; i < 5; i = i + 1 {
            let row = schema.record_new();
            row.int_vals[0] = i64(i + 1);
            row.int_vals[1] = i64((i + 1) * 1000);
            t.table_insert(row);
        }

        // 인덱스 생성 및 재구성
        let idx = index.index_new(1);  // price 컬럼 인덱싱
        let rebuild_err = idx.index_rebuild(&t);
        let t1 = assert_eq_i32(rebuild_err, index.IDX_OK, "index rebuild ok");
        print_result(t1);

        let t2 = assert_eq_i64(idx.key_count, 5, "index key_count=5");
        print_result(t2);

        // 인덱스로 검색
        let row_id, found = idx.index_search(2000);  // price=2000
        let t3 = assert_true(found && row_id == 2, "index search 2000 → row_id=2");
        print_result(t3);

        // 범위 스캔
        let result, count = idx.index_range(1000, 3000);
        let t4 = assert_eq_i32(count, 3, "range [1000,3000] count=3");
        print_result(t4);

        print(idx.index_stats());
        print("Integration tests completed");
    }

    // === Main ===

    func main() {
        print("==========================================");
        print("FreeLang Phase 7 Index Tests");
        print("==========================================");

        test_btree_basic();
        test_range_scan();
        test_str_index();
        test_planner();
        test_integration();

        print("\n==========================================");
        print("All index tests completed!");
        print("==========================================");
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_str(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n == 6 { return "6"; }
        if n == 7 { return "7"; }
        if n == 8 { return "8"; }
        if n == 9 { return "9"; }
        if n < 0 { return "-" + i32_to_str(-n); }
        let d = n / 10;
        let r = n % 10;
        return i32_to_str(d) + i32_to_str(r);
    }

    @inline
    func i64_to_str(n: i64) -> string {
        if n == 0 { return "0"; }
        if n < 0 { return "-" + i64_to_str(-n); }
        return i32_to_str(i32(n));
    }
